VALUES ('MSG-LMP-15', 'PRJ-LUMPINI', '28 ต.ค. 2569 11:56', 'สรุปใบสั่งซื้อท่อน้ำดีตามผังวิศวกร: ท่อ 1 นิ้ว 8 เส้น, ท่อ 1/2 นิ้ว 8 เส้น, ต่อตรง 1 นิ้ว 8 ตัว, ต่อตรง 1/2 นิ้ว 8 ตัว, สามทาง 1 นิ้ว 2 ตัว, สามทางลด 1x1/2 นิ้ว 2 ตัว, งอ 90 ลด 1x1/2 นิ้ว 3 ตัว, บอลวาล์วทองเหลือง Sanwa 1 นิ้ว 1 ตัว, ยูเนี่ยน 1 นิ้ว 1 ตัว', 0, 0, 'แก๊ป (วิศวกร)', 'assets/lumpini/water_pipe_order_map.jpg', 'assets/lumpini/water_pipe_order_map.jpg', 'CHAT_HISTORY', 1, CURRENT_TIMESTAMP);
